def approx(a, b):
    return abs(a - b) < 1e-9

def parse_amount(text):
    cleaned = text.strip()
    if cleaned.startswith("$"):
        cleaned = cleaned[1:]
    cleaned = cleaned.replace(",", "")
    if not cleaned:
        raise ValueError("empty amount")
    return float(cleaned)


def test_parse(text, expected):
    assert approx(parse_amount(text), expected)

def test_rejects(text):
    assert raises(ValueError, parse_amount, text)

run_cases(test_parse, [("12", 12.0), ("$1,234.50", 1234.5), ("  7.25 ", 7.25), ("-3", -3.0), ("$0.10", 0.1)])
